"""Build/commissioning manuals for the four programmes without a custom PCB: AQUAPONICS, GEONODE, SORTER, AGROVER."""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from mlib import *
def write(path, lines): open(os.path.join(ROOT, path), "w").write("\n".join(lines)); print("wrote", path)
STD = "General rules: `manuals/STANDARD_PROCEDURES.md`."

write("aquaponics/MANUFACTURING_MANUAL.md", ["# AQUAPONICS controller: build manual", "",
 "> **Status: control and forecasting core host-tested (13 checks); nothing built or run on live fish.** No new PCB: it runs on the BioTray board (`biotray/`, order-ready). ALL BIOLOGICAL LIMITS ARE PLACEHOLDERS: tune them with an aquaculture expert.", "",
 "## 1. Parts", "", "BioTray board (see `biotray/MANUFACTURING_MANUAL.md`); DS18B20 waterproof probe; analog pH module + probe; analog EC module + probe; analog dissolved-oxygen module + probe; ADS1115 breakout on the I2C header; 12 V circulation pump; 12 V dosing (peristaltic) pump + pH-down reservoir; relay module for the aerator (the FAN output drives the relay coil, flyback is on the board); backup battery aerator (strongly recommended); GFCI-protected supply; sealed enclosure for the wet environment.", "",
 "## 2. Build", "", "1. Build and test the BioTray board first. 2. Wire PUMP1 = circulation, PUMP2 = dosing, FAN = aerator relay coil, sensors as in `aquaponics/docs/DESIGN.md`. 3. Compile `aquaponics/firmware/src/main_aquaponics.cpp` with `firmware/lib/aq_core.c` (Arduino-ESP32 2.x): **the firmware compiles for the ESP32-S3 (tools/esp32_build.sh, 0 warnings, binary in `aquaponics/firmware/release/`); bring it up on a bench.** 4. Run `cd aquaponics/firmware && make test` on a PC (13 checks).", "",
 "## 3. Calibrate", "", "pH with pH 4 and 7 buffers, EC with a standard solution, DO with its 0 % and saturated points, then set the scale factors (placeholders in the skeleton). Set band limits for your species.", "",
 "## 4. Commissioning", "", "Dry run with water only and no fish for at least a week: dosing never exceeds the daily cap, a pulled probe stops dosing (bad-reading lockout), aeration follows the DO forecast, power-cut behaviour is safe. See `aquaponics/docs/TEST_PLAN.md`.", "",
 "## 5. Limits", "", "No ammonia/nitrite/nitrate sensing: test with a kit daily at first. Straight-line forecasts cannot foresee pump failure or feeding spikes. Mains aerators need a proper relay and a rated enclosure. Not tested on live animals. " + STD, ""])

write("geotech/MANUFACTURING_MANUAL.md", ["# GEONODE foundation monitoring network: build manual", "",
 "> **Status: signal-processing design with host-tested node feature code (54 checks) and gateway detector; synthetic vibration only. Nothing built, buried or field-tested.** The node is the MITTI-NETRA board with a LoRa breakout instead of the cellular one.", "",
 "## 1. Parts per node", "", "MITTI-NETRA board (see `mitti-netra/`); UART LoRa module breakout (RAK3172 or RA-08 style, AT commands; India 865-867 MHz plan); antenna; protected Li-ion cell; solar panel; ADXL345 and HX711 are on the board; strain gauges and a waterproof potted enclosure. Gateway: any LoRa gateway or a second node plus a Raspberry Pi running `gateway/anomaly.py`.", "",
 "## 2. Build", "", "1. Make the MITTI-NETRA board. 2. Plug the LoRa module into socket J6 (match the pinout of your breakout: VBAT, GND, TX, RX, PWRKEY, STATUS). 3. Build node firmware from `geotech/node/lib/gt_feat.[ch]`; run `cd geotech/node && make test` and `python3 geotech/gateway/test_anomaly.py` on a PC. 4. Install the node, record a baseline (the thresholds are install-specific), and calibrate `anomaly.py` from it.", "",
 "## 3. Commissioning", "", "See `geotech/docs/TEST_PLAN.md`: tap and vehicle tests against the baseline, alarm only after repeated crack-class windows, LoRa range and duty-cycle check.", "",
 "## 4. Limits", "", "Synthetic data only: the 40-90 Hz cracking signature is an assumption. Buried use needs potting and an antenna strategy not provided here. Not a certified structural-health-monitoring system. " + STD, ""])

write("sorter/MANUFACTURING_MANUAL.md", ["# SORTER bio-robotic sorting platform: build manual", "",
 "> **Status: tracking core host-tested (28 checks), colour vision baseline self-tested on synthetic images, finger geometry generated; no machine built, no real produce imaged.** No new PCB: motion uses the KINETIC controller.", "",
 "## 1. Parts", "", "KINETIC controller (see `kinetic/`); NEMA17 motors and drivers for conveyor (X) and picker (Y, Z); conveyor belt and rollers; Raspberry Pi/Banana Pi and a camera in a controlled-light box; reject actuator or picker; 3D-printed TPU compliant fingers; guarding and an emergency stop.", "",
 "## 2. Build", "", "1. Print the finger: `python3 sorter/cad/gripper.py` writes `sorter/cad/out/finger.stl` (TPU, 3D-printing rules in `STANDARD_PROCEDURES.md`). Load-test it with a force gauge and tune rib count and wall thickness. 2. Assemble the conveyor and picker; fit guards over all pinch points. 3. Compile `sorter/firmware/lib/sr_track.c` into the controller firmware; `cd sorter/firmware && make test` on a PC. 4. `python3 sorter/vision/classify.py --selftest`; then collect labelled images from your own line and replace the colour rules with a trained model (the `classify_*` interface stays).", "",
 "## 3. Calibrate and test", "", "Measure steps per mm of belt, camera-to-pick distance and actuator latency; set the lead accordingly. Run empty belt, then dummy items, then produce; log missed and dropped items. See `sorter/docs/TEST_PLAN.md`.", "",
 "## 4. Limits", "", "Vision is a baseline calibrated on synthetic discs; real produce will break it. Lighting matters more than the algorithm. Finger geometry is untested. Food-contact materials, hygiene and machine guarding are your responsibility. Not safety-rated. " + STD, ""])

write("agrover/MANUFACTURING_MANUAL.md", ["# AGROVER solar field rover: build manual", "",
 "> **Status: navigation, avoidance and power core host-tested in a simulated field (19 checks); chassis plates generated; no custom PCB; nothing built, driven or taken outdoors.**", "",
 "## 1. Parts", "", "ESP32-S3 dev board; 4 x 12 V geared DC motors with quadrature encoders; 2 x dual H-bridge drivers rated at least twice the stall current; 4S LiFePO4 pack with BMS; 50 W solar panel with a LiFePO4 MPPT controller (14.4 V absorption); 3 x ultrasonic sensors with 5 V to 3.3 V level shifting; 20 A fuse, main switch, reverse-polarity protection, **hardware emergency stop**; wheels, M3 hardware.", "",
 "## 2. Build", "", "1. Cut the plates: `python3 agrover/cad/chassis.py` writes `agrover/cad/out/base_plate.svg`, `top_deck.svg`, `sensor_bracket.svg` (laser-cutting rules in `STANDARD_PROCEDURES.md`; check slot sizes against your motors and battery). 2. Mount motors, battery on strap slots, drivers, controller; fuse next to the battery. 3. Compile `agrover/firmware/lib/rv_nav.c` into your ESP32 sketch; `cd agrover/firmware && make test` on a PC.", "",
 "## 3. Commissioning", "", "Wheels off the ground first: direction and encoder sign per wheel; then low speed in a clear area with the emergency stop in hand: straight line, turn, obstacle approach, return-to-charge thresholds (30 % return, 15 % sleep, 40 % wake with sun). See `agrover/docs/TEST_PLAN.md`.", "",
 "## 4. Limits", "", "Dead-reckoning plus reactive avoidance: no GNSS or SLAM, wheel slip will drift the pose. Ultrasonics miss thin stalks. SoC table is typical, not your pack. A moving robot with batteries outdoors needs a safety review. " + STD, ""])
